"""Derived coverage denominators for the bounded original-candidate audit."""
from task_bootstrap import *
from collections import Counter
def main():
 p=STUDY/'reports/WIDE_CAUSAL_EQUIVALENCE.json';r=json.loads(p.read_text());rows=r['rows'];c=r['contract'];seeds={x['seed'] for x in rows};states={x['snapshot'] for x in rows};pairs={(x['snapshot'],x['pool_sha256']) for x in rows};calls=2*sum(x['candidate_count'] for x in rows)
 assert len(pairs)==len(rows) and calls==r['native_validation_calls']
 assert all(x['status']=='PASS' and x['native_acceptance_exact'] and x['target_within_frozen_1e_10'] and x['original_selected']==x['Q_first_selected'] for x in rows)
 out=dict(status='PASS',source_sha256=sha(p),unique_pool_comparisons=len(rows),saved_state_count=len(states),distinct_seed_count=len(seeds),seed_min=min(seeds),seed_max=max(seeds),requested_grid_points=c['seeds']*c['saved_causal_states'],accounted_grid_points=len(rows)+r['duplicate_pools_skipped'],full_registered_grid_covered=len(rows)+r['duplicate_pools_skipped']==c['seeds']*c['saved_causal_states'],duplicate_pools_skipped=r['duplicate_pools_skipped'],actual_candidate_count_distribution=dict(Counter(x['candidate_count'] for x in rows)),native_full_certificate_calls=calls,feasible_candidate_count_distribution=dict(Counter(x['feasible_count'] for x in rows)),roundoff_full_validation_fallback_pools=sum(x['roundoff_fallback'] for x in rows),raw_all_batch_rank_difference_pools=sum(x['original_selected']!=x['raw_all_batch_rank_selected'] for x in rows),with_no_feasible_candidates=sum(x['feasible_count']==0 for x in rows),per_state_comparisons=dict(Counter(x['snapshot'] for x in rows)),physics_attempts=0,interpretation='Existing up-to-six candidate generator may deduplicate to fewer unique candidates after issued masking; certificate call total uses recorded actual cardinality. Identical same-state pools are deduplicated. Full finite grid coverage does not imply continuous-state or Human generalization, nor exercised roundoff fallback if its count is zero.')
 save(STUDY/'reports/WIDE_EQUIVALENCE_COVERAGE.json',out);print(json.dumps({k:v for k,v in out.items() if k!='per_state_comparisons'}))
